async function soulzPresentShare(text) {
  try {
    await ShareSheet.present([text]);
  } catch (e) {
    console.log("SOULZ share fallback: " + e);
    try { Pasteboard.copyString(String(text || "")); } catch (copyError) { console.log("SOULZ copy fallback error: " + copyError); }
    try {
      await web.evaluateJavaScript("if(typeof toast==='function')toast('共有を開けなかったためコピーしました')", false);
    } catch (uiError) {}
  }
}


